'use client'

import { useEffect, useState } from 'react'

const API_URL = 'http://localhost:5000' // Your Flask backend

interface Car {
  id: number
  make: string
  year: number
  price: number
}

export default function Home() {
  const [cars, setCars] = useState<Car[]>([])
  const [make, setMake] = useState('')
  const [year, setYear] = useState('')
  const [price, setPrice] = useState('')
  const [message, setMessage] = useState('')

  const fetchCars = async () => {
    const res = await fetch(`${API_URL}/cars`)
    const data = await res.json()
    setCars(data)
  }

  const addCar = async () => {
    if (!make || !year || !price) {
      setMessage('Please fill in all fields.')
      return
    }

    const res = await fetch(`${API_URL}/cars`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        make,
        year: parseInt(year),
        price: parseFloat(price),
      }),
    })

    const data = await res.json()
    setMessage(`Added: ${data.make} (${data.year}) - $${data.price}`)
    setMake('')
    setYear('')
    setPrice('')
    fetchCars()
  }

  useEffect(() => {
    fetchCars()
  }, [])

  return (
    <main className="max-w-xl mx-auto p-6">
      <h1 className="text-2xl font-bold mb-4">🚘 Car Sale Listing</h1>

      <div className="space-y-2 mb-6">
        <input
          type="text"
          placeholder="Car Make"
          className="w-full border px-3 py-2"
          value={make}
          onChange={(e) => setMake(e.target.value)}
        />
        <input
          type="number"
          placeholder="Year"
          className="w-full border px-3 py-2"
          value={year}
          onChange={(e) => setYear(e.target.value)}
        />
        <input
          type="number"
          placeholder="Price"
          className="w-full border px-3 py-2"
          value={price}
          onChange={(e) => setPrice(e.target.value)}
        />
        <button
          onClick={addCar}
          className="bg-blue-600 text-white px-4 py-2 rounded"
        >
          Add Car
        </button>
      </div>

      {message && <p className="mb-4 text-green-600">{message}</p>}

      <h2 className="text-xl font-semibold mb-2">Available Cars:</h2>
      <ul className="space-y-2">
        {cars.map((car) => (
          <li key={car.id} className="border p-3 rounded">
            <strong>{car.make}</strong> ({car.year}) - ${car.price}
          </li>
        ))}
      </ul>
    </main>
  )
}
